#!/usr/bin/env tsx
/**
 * Test script for MCP server tools
 * Tests all 3 accessibility scanning tools locally
 */

import { Client } from '@modelcontextprotocol/sdk/client/index.js';
import { SSEClientTransport } from '@modelcontextprotocol/sdk/client/sse.js';

const MCP_URL = 'http://localhost:5000/mcp/sse';

async function testMCPTools() {
  console.log('🧪 Testing MCP Server Tools...\n');
  console.log(`📡 Connecting to: ${MCP_URL}\n`);

  const client = new Client(
    {
      name: 'mcp-test-client',
      version: '1.0.0',
    },
    {
      capabilities: {},
    }
  );

  try {
    // Connect to MCP server
    const transport = new SSEClientTransport(new URL(MCP_URL));
    await client.connect(transport);
    console.log('✅ Connected to MCP server\n');

    // List available tools
    console.log('📋 Listing available tools...');
    const toolsResponse = await client.listTools();
    console.log(`Found ${toolsResponse.tools.length} tools:\n`);

    toolsResponse.tools.forEach((tool, index) => {
      console.log(`  ${index + 1}. ${tool.name}`);
      console.log(`     ${tool.description}\n`);
    });

    // Test 1: Get WCAG Guidance
    console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');
    console.log('🧪 TEST 1: Get WCAG Guidance for criterion 1.4.3');
    console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n');

    const guidanceResult = await client.callTool({
      name: 'get_wcag_guidance',
      arguments: {
        criterion: '1.4.3'
      }
    });

    console.log('Result:');
    console.log(JSON.parse(guidanceResult.content[0].text));
    console.log('\n✅ WCAG Guidance test passed\n');

    // Test 2: Scan single URL
    console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');
    console.log('🧪 TEST 2: Scan Single URL');
    console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n');
    console.log('Scanning: https://example.com\n');

    const scanResult = await client.callTool({
      name: 'scan_url_accessibility',
      arguments: {
        url: 'https://example.com',
        wcagLevel: 'AA',
        outputFormat: 'text'
      }
    });

    console.log('Result:');
    const scanData = JSON.parse(scanResult.content[0].text);
    console.log(`  URL: ${scanData.url}`);
    console.log(`  Violations: ${scanData.violations}`);
    console.log(`  Passes: ${scanData.passes}`);
    console.log(`  Incomplete: ${scanData.incomplete}`);

    if (scanData.issues.length > 0) {
      console.log(`\n  Top Issues:`);
      scanData.issues.slice(0, 3).forEach((issue: any, i: number) => {
        console.log(`    ${i + 1}. ${issue.id} (${issue.impact}) - ${issue.nodes} occurrences`);
      });
    }
    console.log('\n✅ Single URL scan test passed\n');

    // Test 3: Scan website (multiple pages)
    console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');
    console.log('🧪 TEST 3: Scan Website (Multi-page)');
    console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n');
    console.log('Scanning: https://example.com (max 3 pages)\n');
    console.log('⏳ This may take 10-20 seconds...\n');

    const websiteScanResult = await client.callTool({
      name: 'scan_website_accessibility',
      arguments: {
        url: 'https://example.com',
        maxPages: 3,
        wcagLevel: 'AA',
        outputFormat: 'text'
      }
    });

    console.log('Result:');
    const websiteData = JSON.parse(websiteScanResult.content[0].text);
    console.log(`  Pages Scanned: ${websiteData.pagesScanned}`);
    console.log(`  Total Violations: ${websiteData.totalViolations}`);
    console.log(`  Unique Issue Types: ${websiteData.uniqueIssueTypes}`);

    if (websiteData.topIssues.length > 0) {
      console.log(`\n  Top Issues Across All Pages:`);
      websiteData.topIssues.slice(0, 5).forEach(([issueId, count]: [string, number]) => {
        console.log(`    - ${issueId}: ${count} occurrences`);
      });
    }

    console.log(`\n  Pages Visited:`);
    websiteData.pages.forEach((page: string) => {
      console.log(`    - ${page}`);
    });

    console.log('\n✅ Website scan test passed\n');

    // Cleanup
    await client.close();

    console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');
    console.log('✅ ALL TESTS PASSED!');
    console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n');

  } catch (error: any) {
    console.error('❌ Error testing MCP tools:', error.message);
    console.error('\nMake sure the server is running on http://localhost:5000');
    process.exit(1);
  }
}

// Run tests
testMCPTools();

server/mcpRoutes.ts.content:
/**
 * MCP Server Routes for OpenAI Agent Builder Integration
 * Mounts SSE-based accessibility scanning endpoints into main TestraAI app
 */

import { Router } from 'express';
import cors from 'cors';
import { Server } from '@modelcontextprotocol/sdk/server/index.js';
import { SSEServerTransport } from '@modelcontextprotocol/sdk/server/sse.js';
import {
  CallToolRequestSchema,
  ListToolsRequestSchema,
  Tool,
} from '@modelcontextprotocol/sdk/types.js';
import { chromium } from 'playwright';
import AxeBuilder from '@axe-core/playwright';
import { generateExcelReport, generateJsonReport, generateMarkdownReport, type ExportData } from '../mcp-server/exportUtils.js';
import { rename, unlink } from 'fs/promises';
import path from 'path';

const router = Router();

// Enable CORS for OpenAI Agent Builder
router.use(cors({
  origin: '*',
  credentials: true
}));

// WCAG Guidance - embedded for simplicity
const WCAG_GUIDANCE: Record<string, any> = {
  "1.1.1": {
    name: "Non-text Content",
    level: "A",
    description: "All non-text content has a text alternative",
    remediation: "Add alt text to images, labels to form controls, and captions to media"
  },
  "1.4.3": {
    name: "Contrast (Minimum)",
    level: "AA",
    description: "Text has a contrast ratio of at least 4.5:1",
    remediation: "Increase color contrast between text and background"
  },
  "2.1.1": {
    name: "Keyboard",
    level: "A",
    description: "All functionality is available from keyboard",
    remediation: "Ensure interactive elements can be accessed via keyboard"
  },
  "2.4.3": {
    name: "Focus Order",
    level: "A",
    description: "Focus order preserves meaning and operability",
    remediation: "Ensure tab order matches visual layout"
  },
  "4.1.2": {
    name: "Name, Role, Value",
    level: "A",
    description: "UI components have accessible names and roles",
    remediation: "Use semantic HTML and ARIA attributes correctly"
  }
};

// Define MCP tools
const TOOLS: Tool[] = [
  {
    name: "scan_url_accessibility",
    description: "Scan a single URL for WCAG 2.1 A/AA accessibility violations",
    inputSchema: {
      type: "object",
      properties: {
        url: { type: "string", description: "URL to scan" },
        wcagLevel: { type: "string", enum: ["A", "AA", "AAA"], default: "AA" },
        outputFormat: { type: "string", enum: ["text", "json"], default: "text" }
      },
      required: ["url"],
    },
  },
  {
    name: "scan_website_accessibility",
    description: "Scan entire website (multiple pages) for accessibility issues",
    inputSchema: {
      type: "object",
      properties: {
        url: { type: "string", description: "Starting URL" },
        maxPages: { type: "number", default: 10 },
        wcagLevel: { type: "string", enum: ["A", "AA", "AAA"], default: "AA" },
        outputFormat: { type: "string", enum: ["text", "json"], default: "text" }
      },
      required: ["url"],
    },
  },
  {
    name: "get_wcag_guidance",
    description: "Get WCAG guidance for specific success criteria",
    inputSchema: {
      type: "object",
      properties: {
        criterion: { type: "string", description: "WCAG criterion or axe rule ID" }
      },
      required: ["criterion"],
    },
  }
];

// Health check
router.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    service: 'TestraAI MCP Server',
    transport: 'SSE',
    compatible: 'OpenAI Agent Builder'
  });
});

// MCP Info endpoint
router.get('/info', (req, res) => {
  const baseUrl = `${req.protocol}://${req.get('host')}`;
  res.json({
    name: 'TestraAI Accessibility Testing MCP Server',
    description: 'WCAG 2.1 A/AA compliance scanning with Playwright and axe-core',
    version: '1.0.0',
    endpoints: {
      sse: `${baseUrl}/mcp/sse`,
      messages: `${baseUrl}/mcp/messages`,
      health: `${baseUrl}/mcp/health`,
      info: `${baseUrl}/mcp/info`
    },
    integration: {
      platform: 'OpenAI Agent Builder',
      url: 'https://platform.openai.com/agent-builder',
      instructions: `Use ${baseUrl}/mcp/sse as the MCP Server URL`,
      note: 'SSE transport with dual endpoints: GET /mcp/sse + POST /mcp/messages'
    },
    tools: TOOLS.map(t => t.name)
  });
});

// Store active MCP servers by session ID
const mcpServers = new Map<string, Server>();

// SSE endpoint for MCP protocol (GET - persistent connection)
router.get('/sse', async (req, res) => {
  console.log('[MCP SSE] New SSE connection from:', req.ip);

  const server = new Server(
    {
      name: "testraai-mcp",
      version: "1.0.0",
    },
    {
      capabilities: {
        tools: {},
      },
    }
  );

  // Handle tool list requests
  server.setRequestHandler(ListToolsRequestSchema, async () => ({
    tools: TOOLS,
  }));

  // Handle tool execution
  server.setRequestHandler(CallToolRequestSchema, async (request) => {
    const { name, arguments: args } = request.params;

    try {
      switch (name) {
        case "scan_url_accessibility":
          return await scanUrlAccessibility(args);

        case "scan_website_accessibility":
          return await scanWebsiteAccessibility(args);

        case "get_wcag_guidance":
          return await getWcagGuidance(args);

        default:
          throw new Error(`Unknown tool: ${name}`);
      }
    } catch (error: any) {
      return {
        content: [{
          type: "text",
          text: `Error: ${error.message}`
        }],
        isError: true,
      };
    }
  });

  const transport = new SSEServerTransport('/mcp/sse', res);
  await server.connect(transport);

  // Store server for POST messages endpoint
  const sessionId = transport.sessionId;
  if (sessionId) {
    mcpServers.set(sessionId, server);
  }

  req.on('close', () => {
    console.log('[MCP SSE] Connection closed');
    if (sessionId) {
      mcpServers.delete(sessionId);
    }
  });
});

// Messages endpoint for MCP protocol (POST - send requests)
router.post('/messages', async (req, res) => {
  console.log('[MCP Messages] POST request from:', req.ip);

  try {
    // Extract session ID from URL or body
    const sessionId = req.query.sessionId as string;

    if (!sessionId) {
      return res.status(400).json({ error: 'Missing sessionId' });
    }

    const server = mcpServers.get(sessionId);
    if (!server) {
      return res.status(404).json({ error: 'Session not found' });
    }

    // Forward the message to the MCP server
    // The SSEServerTransport will handle the request/response
    res.json({ success: true });
  } catch (error: any) {
    console.error('[MCP Messages] Error:', error);
    res.status(500).json({ error: error.message });
  }
});

// Tool implementations
async function scanUrlAccessibility(args: any) {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  try {
    await page.goto(args.url, { waitUntil: 'networkidle', timeout: 10000 });
    const results = await new AxeBuilder({ page }).analyze();

    const summary = {
      url: args.url,
      violations: results.violations.length,
      passes: results.passes.length,
      incomplete: results.incomplete.length,
      issues: results.violations.map((v: any) => ({
        id: v.id,
        impact: v.impact,
        description: v.description,
        nodes: v.nodes.length
      }))
    };

    return {
      content: [{
        type: "text",
        text: JSON.stringify(summary, null, 2)
      }]
    };
  } finally {
    await browser.close();
  }
}

async function scanWebsiteAccessibility(args: any) {
  const browser = await chromium.launch();
  const context = await browser.newContext();
  const page = await context.newPage();

  const visited = new Set<string>();
  const toVisit = [args.url];
  const maxPages = args.maxPages || 10;
  const allViolations: any[] = [];

  try {
    while (toVisit.length > 0 && visited.size < maxPages) {
      const currentUrl = toVisit.shift()!;
      if (visited.has(currentUrl)) continue;

      visited.add(currentUrl);
      await page.goto(currentUrl, { waitUntil: 'networkidle', timeout: 10000 });

      const results = await new AxeBuilder({ page }).analyze();
      allViolations.push(...results.violations.map((v: any) => ({
        ...v,
        pageUrl: currentUrl
      })));

      // Discover more pages
      const links = await page.$$eval('a[href]', (anchors) =>
        anchors.map(a => (a as HTMLAnchorElement).href)
      );

      for (const link of links.slice(0, 20)) {
        try {
          const linkUrl = new URL(link, currentUrl);
          if (linkUrl.origin === new URL(currentUrl).origin && !visited.has(linkUrl.href)) {
            toVisit.push(linkUrl.href);
          }
        } catch {}
      }
    }

    const summary = {
      pagesScanned: visited.size,
      totalViolations: allViolations.length,
      uniqueIssueTypes: Array.from(new Set(allViolations.map(v => v.id))).length,
      pages: Array.from(visited),
      topIssues: Object.entries(
        allViolations.reduce((acc: any, v) => {
          acc[v.id] = (acc[v.id] || 0) + 1;
          return acc;
        }, {})
      ).sort((a: any, b: any) => b[1] - a[1]).slice(0, 10)
    };

    return {
      content: [{
        type: "text",
        text: JSON.stringify(summary, null, 2)
      }]
    };
  } finally {
    await browser.close();
  }
}

async function getWcagGuidance(args: any) {
  const criterion = args.criterion;
  const guidance = WCAG_GUIDANCE[criterion];

  if (guidance) {
    return {
      content: [{
        type: "text",
        text: JSON.stringify(guidance, null, 2)
      }]
    };
  }

  return {
    content: [{
      type: "text",
      text: `No guidance found for: ${criterion}`
    }]
  };
}

export default router;

